function minDifference(nums) {
  const n = nums.length;
  if (n <= 4) {
    return 0;
  }

  nums.sort((a, b) => a - b);
  let best = Infinity;

  for (let removeLow = 0; removeLow <= 3; removeLow++) {
    const removeHigh = 3 - removeLow;
    const gap = nums[n - 1 - removeHigh] - nums[removeLow];
    best = Math.min(best, gap);
  }

  return best;
}

