function minDifference(nums) {
  // Try every set of up to three indices to overwrite; the overwritten values can hide inside the rest's range.
  const n = nums.length;
  const k = Math.min(3, n);
  let best = Infinity;
  const chosen = [];
  const visit = (start) => {
    if (chosen.length === k) {
      const rest = nums.filter((_, i) => !chosen.includes(i));
      const gap = rest.length === 0 ? 0 : Math.max(...rest) - Math.min(...rest);
      if (gap < best) best = gap;
      return;
    }
    for (let i = start; i < n; i++) {
      chosen.push(i);
      visit(i + 1);
      chosen.pop();
    }
  };
  visit(0);
  return best;
}

