function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 9);
  const mode = Math.floor(rand() * 3);
  const span = mode === 0 ? 5 : mode === 1 ? 100 : 1000000000;
  const nums = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  return [nums];
}
